// مراقبة مقياس Cumulative Layout Shift (CLS) بنظام نوافذ الجلسة
let clsScore = 0;
let currentSessionScore = 0;
let currentSessionEntries = [];

const observer = new PerformanceObserver((entryList) => {
  for (const entry of entryList.getEntries()) {
    // احتساب الإزاحات غير المتوقعة فقط (بدون تفاعل أخير من المستخدم)
    if (!entry.hadRecentInput) {
      const firstSessionEntry = currentSessionEntries[0];
      const lastSessionEntry = currentSessionEntries[currentSessionEntries.length - 1];

      // شروط نافذة الجلسة: فاصل أقل من 1000ms وأقصى مدة للنافذة 5000ms
      if (
        currentSessionScore &&
        entry.startTime - lastSessionEntry.startTime < 1000 &&
        entry.startTime - firstSessionEntry.startTime < 5000
      ) {
        currentSessionScore += entry.value;
        currentSessionEntries.push(entry);
      } else {
        currentSessionScore = entry.value;
        currentSessionEntries = [entry];
      }

      // تسجيل أكبر نافذة جلسة (The Largest Burst)
      if (currentSessionScore > clsScore) {
        clsScore = currentSessionScore;
        console.log(`⚠️ نافذة CLS قياسية جديدة: ${clsScore.toFixed(4)}`);
      }
    }
  }
});

observer.observe({ type: 'layout-shift', buffered: true });
